'use strict';
const setupSteps=['Seu pedido','Produção','Entrega'];
function setupValid(s){const c=s.setup;return c===undefined||c&&Number.isInteger(c.step)&&c.step>=0&&c.step<(c.version===2?3:6)&&(c.version===undefined||c.version===2)&&typeof c.project==='string'&&(!c.project||s.projects.some(p=>p.id===c.project))&&typeof c.task==='string'&&(!c.task||(s.tasks||[]).some(t=>t.id===c.task))}
function setupOf(){const s=studio();if(!s.setup)s.setup={version:2,step:0,project:activeProjects()[0]?.id||'',task:''};if(s.setup.version!==2){s.setup.step=s.setup.step<3?0:s.setup.step<5?1:2;s.setup.version=2}return s.setup}
function setupTask(){const c=setupOf();return studio().tasks.find(t=>t.id===c.task&&t.project===c.project)||studio().tasks.find(t=>t.project===c.project)}
function setupReady(step){const t=setupTask();if(step===0)return !!t;if(step===1)return !!t&&!!t.plan.trim()&&!!t.execution&&t.execution.handoffs.length===t.creators.length&&executionValid(t);return !!t&&t.status==='Entregue'&&evalsComplete(t)}
function setupPage(){const c=setupOf(),pr=project(c.project),t=setupTask(),lead=person(pr?.directorId);let body='';
 if(c.step===0)body=`<div class="setup-example"><h3>Uma orientação completa. Sem repetir campos.</h3><p>Conte o que quer receber e em quanto tempo. O contexto da marca e o perfil da diretora já fazem parte do trabalho.</p><button class="btn primary" data-intake="start">Dar briefing por áudio ou texto ${ico('pen')}</button></div><details class="strategy-brief"><summary>Projeto e equipe · ajustar quando precisar</summary><label class="field"><span>Projeto</span><select id="setup-project"><option value="">Escolha um projeto</option>${activeProjects().map(p=>`<option value="${esc(p.id)}" ${c.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="actions"><button class="btn" data-studio="new-project">Novo projeto</button>${c.project?`<button class="btn" data-studio="project" data-id="${esc(c.project)}">Contexto da marca</button><button class="btn" data-direction="manage" data-id="${esc(c.project)}">Direção do projeto</button>`:''}<button class="btn" data-studio="new-person">Novo perfil</button></div>${lead?.id?`<button class="btn" data-studio="person" data-id="${esc(lead.id)}">Ajustar ${esc(lead.name)}</button>`:''}</details>${t?`<label class="field"><span>Pedido em acompanhamento</span><select id="setup-task">${studio().tasks.filter(x=>x.project===c.project).map(x=>`<option value="${esc(x.id)}" ${t.id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><p class="long-copy">${esc(t.brief)}</p><p>${esc(person(t.director).name)} · ${durationLabel(t.minutes)}</p><button class="btn" data-agency="edit-task" data-id="${esc(t.id)}">Ajustar este pedido</button>`:''}<button class="btn" data-setup="new-task">Preencher direto</button>`;
 if(c.step===1)body=t?`<h3>${esc(t.title)}</h3><p class="long-copy">${esc(t.plan||'A diretora organiza a equipe, os repasses e a revisão a partir do seu pedido.')}</p><div class="deadline-contract"><span class="eyebrow">PRAZO TOTAL</span><h3>${durationLabel(t.minutes)}</h3><p>${t.creators.length} criador(es) · ${esc(person(t.director).name)} na direção</p>${t.execution?.deadlineAt?`<small>Limite: ${esc(dateLabel(t.execution.deadlineAt))}</small>`:''}</div><div class="actions"><button class="btn primary" data-agency="task-plan" data-id="${esc(t.id)}">Equipe e plano</button><button class="btn" data-quality="plan" data-id="${esc(t.id)}">Prompts e repasses</button><button class="btn" data-agency="export-task" data-id="${esc(t.id)}">Levar ao ChatGPT</button></div><p class="form-context">O pedido já acompanha os prompts. O motor de execução automática ainda não está conectado; registre aqui o plano da diretora.</p>`:'<p>Registre o pedido antes de organizar a produção.</p>';
 if(c.step===2)body=t?`<h3>${esc(t.title)}</h3><div class="actions"><button class="btn primary" data-agency="task-result" data-id="${esc(t.id)}">Registrar material</button><button class="btn" data-quality="eval" data-id="${esc(t.id)}">Avaliar entrega</button><button class="btn" data-agency="task" data-id="${esc(t.id)}">Ver todos os registros</button></div><p class="form-context">${setupReady(2)?'Entrega e avaliações registradas.':'A conclusão exige material real e avaliações aprovadas. Use parcial ou revisar quando houver pendências.'}</p>`:'<p>Registre o pedido primeiro.</p>';
 return `${heading('Do pedido à entrega.','Três passos. Você ajusta apenas o que precisar.')}<nav class="setup-steps compact" aria-label="Etapas da sprint">${setupSteps.map((label,i)=>`<button data-setup="step" data-step="${i}" class="${i===c.step?'current':''}" ${i===c.step?'aria-current="step"':''}><b>0${i+1}</b><span>${label}</span>${setupReady(i)?'<small>✓</small>':''}</button>`).join('')}</nav><section class="setup-panel"><div class="section-heading"><div><span class="eyebrow">ETAPA ${c.step+1} DE 3</span><h2>${setupSteps[c.step]}</h2></div></div>${body}<div class="setup-footer"><button class="btn" data-setup="back" ${c.step===0?'disabled':''}>Voltar</button>${c.step<2?'<button class="btn primary" data-setup="next">Continuar</button>':'<button class="btn primary" data-setup="another">Novo pedido</button>'}</div></section>`;
}
function setupGo(step){const c=setupOf();if(!Number.isInteger(step)||step<0||step>2)return false;if(step>c.step){for(let i=c.step;i<step;i++)if(!setupReady(i)){toast('Conclua '+setupSteps[i]+' antes de continuar.');return false}}c.step=step;persist('Avançou na sprint: '+setupSteps[step]);render();return true}
document.addEventListener('click',e=>{const b=e.target.closest('[data-setup]');if(!b)return;const c=setupOf(),a=b.dataset.setup;if(a==='next')setupGo(Math.min(2,c.step+1));if(a==='back')setupGo(Math.max(0,c.step-1));if(a==='step')setupGo(Number(b.dataset.step));if(a==='new-task')taskForm(undefined,c.project);if(a==='another'){c.step=0;persist('Preparou outro pedido');openIntake()}});
document.addEventListener('change',e=>{if(e.target.id==='setup-project'){const c=setupOf();c.project=e.target.value;c.task='';c.step=0;persist('Escolheu projeto');render()}if(e.target.id==='setup-task'){setupOf().task=e.target.value;persist('Escolheu pedido');render()}});
